      logic: () => StandardOPs.oclIsUndefined(existingCard),
      description: "existingCard.oclIsUndefined()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => true,
        description: "true",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newCard: BankCard;
    return l({
      execute: () => (newCard = new BankCard()),
      description: "newCard.oclIsNew()",
    })
      .if({
        logic: () =>
          l({
            logic: () => cardNotExist,
            description: "cardNotExist",
          }),
        description: "cardNotExist",
        then: l({
          execute: () => getRepository(BankCard).push(newCard),
          description: "BankCard.allInstance()->includes(newCard)",
        })
          .and({
            execute: () => (newCard.CardID = cardid),
            description: "newCard.CardID=cardid",
          })
          .and({
            execute: () => (newCard.CardStatus = cardstatus),
            description: "newCard.CardStatus=cardstatus",
          })
          .and({
            execute: () => (newCard.Catalog = catalog),
            description: "newCard.Catalog=catalog",
          })
          .and({
            execute: () => (newCard.Password = password),
            description: "newCard.Password=password",
          })
          .and({
            execute: () => (newCard.Balance = balance),
            description: "newCard.Balance=balance",
          }),
        else: l({
          logic: () => true,
          description: "true",
        }),
      })
      .and({
        execute: () => cardNotExist,
        description: "result=cardNotExist",
      })
      .build().value;
    /*Postcondition End*/
  }
